import test from 'node:test';import assert from 'node:assert/strict';import {readFile} from 'node:fs/promises';
const emailTriageArtifact='I will retain my first choices, the supplied synthetic case and a message-triage note citing each message ID, the separate receiver trust-register entry, the accepted or rejected Authentication-Results record, From and expected-sender domains, Reply-To and link domains, SPF MAIL FROM, DKIM signing domain and DMARC result, plus each decision, discrepancy, uncertainty, next check, correction and help used.';
const emailTriageDecision='I will use only the package’s supplied decoded `.test` domains, Authentication-Results records and separate fictional receiver trust register. I will accept a result only when its record ID is registered and its `authserv-id` matches the trusted receiving relay; apply the package’s strict exact-domain alignment rule; and use the ordered labels for no trusted result, reported DMARC failure, unresolved authentication, authenticated domains with discrepancies and authenticated domains that still require content review. I will treat SPF, DKIM and DMARC values as supplied receiver outcomes, not results I independently derived from DNS or signature verification. I will keep domain authentication separate from a person’s identity, intent and message safety, and will not treat a differing expected-sender, Reply-To or link domain as proof of phishing. The lab performs no DNS query, signature validation, arbitrary-email parsing, ARC, relaxed-alignment, attachment or URL-content analysis. A helper or reference match establishes only bounded package behavior, not a live message’s authenticity, factual completeness, professional use, completion, mastery or independent assessment.';
const shellArtifact='I will retain my first decisions, the supplied fictional command notebook and a worksheet citing each record ID, shell, working directory, actual arguments, match, error and status fields, pipeline-stage statuses, byte margin, service state, process and expected PIDs, listener bind, port and owner fields, uncertainty and smallest next read-only check.';
const shellDecision='I will use only the supplied fictional command notebook for this planned route; its commands and result fields are transcriptions, and the helper reads JSON but does not execute commands or inspect a host. I will apply the stated lexical path and status rules: actual argument tokens and the working directory support only the bounded path result, not links, permissions or a live file check; grep, PowerShell and pipeline statuses must be tied to the named command and captured fields, and an empty result differs from an error; and the byte result tests only the stated budget. A supplied service state does not establish the expected state or cause; a PID and process-name match does not establish identity or intent and may change; and a loopback or wildcard listener and owner PID do not establish remote reachability. The optional Linux and Windows live lanes were not run during package authoring and will remain unperformed unless I retain separate live evidence. I will not elevate privileges, install tools, change or start or stop a service, or scan a remote system. A helper or reference match will not prove live command execution, host state, safety, professional use, completion, mastery or independent assessment.';
const encryptionKeyArtifact='I will retain first predictions, the supplied synthetic transform, key and restore ledgers, helper observations, and a recovery-dependency worksheet citing exact sample, backup, key and evidence-reference IDs, byte boundaries, computed and supplied values, the trusted-baseline assumption, decisions, uncertainty and next checks.';
const encryptionKeyDecision='I will use only supplied fictional recovery records and dummy UTF-8 text; distinguish Base64 encoding, SHA-256 change detection and encryption for confidentiality; and trace each saved object to its exact required key, key state, operator access, ciphertext evidence, attempt record and restored-content comparison. I will treat the trusted baseline as an exercise assumption not established by hashing, and distinguish actual Base64 decoding and SHA-256 computation from fictional encryption and decryption receipts. I will not treat a key ID, replacement key, duplicate ciphertext or supplied success receipt as proof of recoverability, and will not claim real encryption, decryption, confidentiality, restore success, future recoverability, professional use, completion, mastery or independent assessment.';
const fileTypeArtifact='I will retain my first prediction and decisions, the supplied synthetic case, notes, the practical receipt, the source and copied dummy files, and a file-type worksheet citing each item ID, filename and extension, reported MIME label, total size, inspected prefix length and hexadecimal bytes, source-before, source-after and copied-file SHA-256 values, the source-unchanged result, signature decision, alternative explanation, uncertainty and next check.';
const fileTypeDecision='I will use only the package’s supplied synthetic cases and bounded local operation: create harmless PNG bytes, a tiny made-up SQLite database, plain text or short byte samples in a fresh lab folder; copy and hash them; inspect only their size and up to the first 16 bytes; and execute no sample. I will check zero length first, then require the complete eight-byte PNG signature or complete 16-byte SQLite signature; treat filename extensions and reported MIME labels as labels rather than proof; and leave incomplete or unsupported signatures type-undetermined. I will keep the fictional worksheet separate from the practical receipt and treat matching source hashes only as evidence that the source bytes stayed unchanged, not that metadata stayed unchanged or that a copy is safe. A signature match is only a format clue, and an extension mismatch does not establish malware or whole-file validity. Only PNG and SQLite signatures are recognized. I will use no personal file, device or browser profile and run no antivirus, full format validator or executable analysis. The saved package checks and practical receipts are maintainer evidence, not evidence that I performed the task. A helper or reference match, unit test or hash result will not establish factual completeness, a real file’s safety, professional use, completion, mastery or independent assessment.';
const fileTimeArtifact='I will retain my first prediction and decisions, the supplied synthetic case, notes, the practical receipt, the generated source and output dummy files, and a file-time worksheet citing each item ID, recorded operation, before and after SHA-256 values, before and after mtime_ns values, the separate byte-equality and modified-time-equality results, the exact modified-time difference in nanoseconds, my decision, an alternative explanation, uncertainty and next check. For the practical operation I will also retain the observed size, pre-hash atime_ns, ctime_ns with its platform note, birthtime_ns when exposed, platform, source SHA-256 values before and after, and the source-bytes-unchanged result.';
const fileTimeDecision='I will use only the package’s supplied synthetic scenarios and bounded local operation in a fresh folder under this lab’s run/ directory: create one harmless dummy text file, set a known modified time, and perform only copy2, copyfile, or a controlled write followed by resetting the copied file’s modified time. I will compare SHA-256 and mtime_ns independently and use only the four supported outcomes: content-equal-time-equal, content-equal-time-differs, content-differs-time-equal, or content-and-time-differ. I will keep the fictional worksheet separate from the actual local receipt; note that access time was collected before hashing; record birth time only when Python exposes it; and treat ctime according to the recorded platform, not as a portable creation time. Matching hashes support byte equality only at the recorded checks, and a matching source hash supports only that the source bytes stayed unchanged; neither establishes unchanged metadata, file safety, who performed an action, when an action occurred, or why a timestamp has a value. File times can be copied or set explicitly, and filesystem, operating-system, access-time, birth-time, timestamp-precision, cross-filesystem and clock behavior remain outside this single local experiment unless separately tested. I will use no personal file, coursework, disk, device or browser profile and will make no claim of real forensic acquisition, factual completeness, professional use, completion, mastery or independent assessment. A reference match, unit test, hash result or saved maintainer receipt will establish only bounded package behavior or recorded byte identity, not my performance or a real-world conclusion.';
const deletedFileArtifact='I will retain my first prediction and decisions, the supplied synthetic case and notes, the practical receipt, the generated source image, read-only working copy, recovery log and separately extracted candidate when one is produced, plus a deleted-file-recovery worksheet citing the item ID, generated 32 KiB FAT12 geometry, directory-entry state and `0xe5` marker, FAT-copy agreement, cluster and allocation state, declared and candidate byte counts, known-file and extracted-candidate SHA-256 values, source-before and source-after hashes, decision, alternative explanation, uncertainty and next check.';
const deletedFileDecision='I will use only the package’s supplied synthetic scenarios and bounded local operation in a fresh folder under this lab’s `run/` directory: construct the generated 32 KiB FAT12 layout in memory, write it only as a new ordinary image file, model deletion of one training entry and release of its cluster, reopen the working copy read-only, and extract at most one supported one-cluster candidate into a separate output folder. I will never mount the image or supply a device, personal file, coursework, browser profile or other external evidence. I will require the exact training geometry and agreeing FAT copies; distinguish an absent directory candidate from an allocated cluster or file larger than 512 bytes; compare candidate length with declared size before comparing SHA-256; and call a match only when both size and hash equal the known training file. I will keep the fictional worksheet separate from the actual local receipt and treat matching source hashes only as evidence that the source bytes stayed unchanged at the recorded checks, not that metadata stayed unchanged. An `0xe5` entry, free cluster or extracted byte sequence does not establish original provenance, who deleted a file, when or why deletion occurred, or complete recovery of arbitrary media. A known-file match establishes only byte equality for this generated training item. Missing or differing bytes do not prove that all prior data is gone or explain the difference. Mounting, recovery suites, fragmented files, physical disks, TRIM and damaged media remain untested. Reference matches, unit tests, hashes and maintainer receipts establish only bounded package behavior or recorded byte identity; they do not prove my performance, factual completeness, professional use, completion, mastery or independent assessment.';
const occurrenceCount=(value,needle)=>value.split(needle).length-1;
test('contact identity and standalone public scope are fixed',async()=>{const c=JSON.parse(await readFile(new URL('../site.config.json',import.meta.url)));assert.equal(c.base,'/');assert.equal(c.origin,'https://jeremy-bryant.pages.dev');assert.equal(c.source,'/source/');assert.equal(c.github,undefined);assert.match(c.linkedin,/linkedin\.com\/in\/jeremy-bryant-61347a445\//);});
test('case study retains incomplete extension and attribution',async()=>{const html=await readFile(new URL('../dist/lg-webos-lab/index.html',import.meta.url),'utf8');assert.match(html,/Bluetooth controller behaviour had not been verified/);assert.match(html,/work of their upstream developers/);assert.match(html,/not an original exploit discovery/);});
test('production is an independent static Pages target with no existing domain routes',async()=>{const config=JSON.parse(await readFile(new URL('../wrangler.jsonc',import.meta.url)));assert.deepEqual(Object.keys(config).sort(),['compatibility_date','name','pages_build_output_dir']);assert.equal(config.name,'jeremy-bryant');assert.equal(config.pages_build_output_dir,'./dist');});
test('GRC route reaches the complete pack and does not claim an assessed result',async()=>{
  const home=await readFile(new URL('../dist/index.html',import.meta.url),'utf8');
  const grc=await readFile(new URL('../dist/security-labs/grc/index.html',import.meta.url),'utf8');
  const study=await readFile(new URL('../dist/security-labs/grc/loan-cupboard/index.html',import.meta.url),'utf8');
  const review=await readFile(new URL('../dist/security-labs/grc/public-control-review/index.html',import.meta.url),'utf8');
  const lab=await readFile(new URL('../dist/lab-files/risk-register/index.html',import.meta.url),'utf8');
  assert.match(home,/href="\/security-labs\/grc\/"/);
  assert.match(grc,/href="\/lab-files\/risk-register\/#grc-pack"/);
  assert.match(grc,/href="\/security-labs\/grc\/loan-cupboard\/"/);
  assert.match(grc,/href="\/security-labs\/grc\/public-control-review\/"/);
  assert.match(study,/Fictional, paper-only/);
  assert.match(study,/acceptance: false/);
  assert.match(study,/Exposure is not confirmed/);
  assert.match(review,/115 requests passed with zero errors/);
  assert.match(review,/account authentication, recovery and browser-level policy behaviour were outside this review/);
  assert.match(lab,/id="grc-pack"/);
  assert.match(lab,/Independent completion: \*\*not claimed\*\*/);
});
