  assert.match(goal,/I will use only the supplied synthetic evidence, not a live capture, and will not treat the exercise as proof of packet loss, application success, answer truth, professional use, completion or mastery\./);
  assert.match(goal,/02 · <a href="\/lab-files\/shell-troubleshooting\/">Use shell commands for read-only troubleshooting<\/a>/);
  assert.match(goal,/03 · <a href="\/lab-files\/isolated-lab-workbench\/">Disposable lab workbench — supplied evidence<\/a>/);
  const goalText=goal.replace(/<code>(.*?)<\/code>/g,'`$1`').replace(/<[^>]+>/g,'');
