  assert.ok(goalText.includes(shellArtifact));
  assert.ok(goalText.includes(shellDecision));
  assert.match(goal,/supplied-evidence workbench boundary diagram and worksheet citing the fictional VM and snapshot IDs, all eight adapter slots, guest route and address summary, listed host-transfer settings, loopback response and stop check, disk mode, and baseline, changed and restored hashes/);
  assert.match(goal,/require a disposable VM record; all eight adapter slots disabled or not attached; no default route, non-loopback address or listed host-transfer path/);
  assert.match(goal,/HTTP 200 with exact <code>BASELINE\\n<\/code> body on <code>127\.0\.0\.1<\/code> and refusal after stop/);
  assert.match(goal,/optional VM and all live and hands-on steps will remain unperformed/);
  assert.match(goal,/helper will not inspect a real host or guest or certify isolation or safety/);
  assert.match(goal,/not treat a snapshot as a backup or any result as proof of professional use, completion, mastery or independent assessment/);
  assert.match(goal,/05 · <a href="\/lab-files\/dns-cache-records\/">DNS cache records<\/a>/);
